using Dapper;
namespace Amora;
public static class Overview
{
    public static void MapOverview(this WebApplication app){app.MapGet("/api/overview",async(HttpContext ctx,Db db)=>{
        var today=DateOnly.FromDateTime(DateTime.UtcNow.AddHours(7));DateOnly Parse(string key,DateOnly fallback){var raw=ctx.Request.Query[key].ToString();if(raw=="")return fallback;Check.That(DateOnly.TryParseExact(raw,"yyyy-MM-dd",out var d),"Ngày lọc không hợp lệ.");return d;}
        var from=Parse("from",new(today.Year,today.Month,1));var to=Parse("to",today);Check.That(to>=from&&to.DayNumber-from.DayNumber<=365,"Khoảng lọc từ 1 đến 366 ngày.");
        Guid? owner=null;var rawOwner=ctx.Request.Query["ownerId"].ToString();if(rawOwner!=""){Check.That(Guid.TryParse(rawOwner,out var id),"CTV không hợp lệ.");owner=id;}Check.That(ctx.User().Manager||owner is null||owner==ctx.User().Id,"Không có quyền xem CTV khác.",403);
        var args=new Dapper.DynamicParameters(new{manager=ctx.User().Manager,uid=ctx.User().Id,from=DateTime.SpecifyKind(from.ToDateTime(TimeOnly.MinValue).AddHours(-7),DateTimeKind.Utc),to=DateTime.SpecifyKind(to.AddDays(1).ToDateTime(TimeOnly.MinValue).AddHours(-7),DateTimeKind.Utc)});args.Add("owner",owner,System.Data.DbType.Guid);
        await using var c=await db.Open();await using var tx=await c.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead);
        const string scope="(@manager OR owner_id=@uid) AND (@owner IS NULL OR owner_id=@owner)";
        var quotes=await c.QuerySingleAsync("SELECT count(*) AS created,count(*) FILTER(WHERE status='draft') AS draft,count(*) FILTER(WHERE status='sent') AS sent,count(*) FILTER(WHERE status='accepted') AS accepted,count(*) FILTER(WHERE status='rejected') AS rejected FROM quotes WHERE "+scope+" AND created_at>=@from AND created_at<@to",args,tx);
        var live=await c.QuerySingleAsync("SELECT count(*) FILTER(WHERE status='sent' AND valid_until>=(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) AS waiting,count(*) FILTER(WHERE status='sent' AND valid_until<(now() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date) AS expired FROM quotes WHERE "+scope,args,tx);
        var orders=await c.QuerySingleAsync("SELECT COALESCE(sum(subtotal) FILTER(WHERE status='completed' AND completed_at>=@from AND completed_at<@to),0) AS revenue,count(*) FILTER(WHERE status='completed' AND completed_at>=@from AND completed_at<@to) AS completed,count(*) FILTER(WHERE status IN ('pending','confirmed','shipping')) AS processing FROM orders WHERE "+scope,args,tx);
        var commissions=await c.QuerySingleAsync("SELECT COALESCE(sum(amount) FILTER(WHERE status='pending'),0) AS pending,COALESCE(sum(amount) FILTER(WHERE status='approved'),0) AS approved,COALESCE(sum(amount) FILTER(WHERE status='paid'),0) AS paid FROM commissions WHERE (@manager OR user_id=@uid) AND (@owner IS NULL OR user_id=@owner)",args,tx);
        var recent=await c.QueryAsync("SELECT q.id,q.code,q.customer_snapshot->>'name' AS customer_name,q.subtotal+q.shipping AS total,q.status,q.valid_until,q.created_at,u.name AS owner_name FROM quotes q JOIN users u ON u.id=q.owner_id WHERE (@manager OR q.owner_id=@uid) AND (@owner IS NULL OR q.owner_id=@owner) AND q.created_at>=@from AND q.created_at<@to ORDER BY q.created_at DESC,q.id DESC LIMIT 8",args,tx);
        var team=ctx.User().Manager?await c.QueryAsync("SELECT u.id,u.name,u.active,(SELECT count(*) FROM quotes q WHERE q.owner_id=u.id AND q.created_at>=@from AND q.created_at<@to) AS quotes_count,(SELECT count(*) FROM quotes q WHERE q.owner_id=u.id AND q.status='accepted' AND q.created_at>=@from AND q.created_at<@to) AS accepted,(SELECT count(*) FROM orders o WHERE o.owner_id=u.id AND o.status='completed' AND o.completed_at>=@from AND o.completed_at<@to) AS completed,(SELECT COALESCE(sum(subtotal),0) FROM orders o WHERE o.owner_id=u.id AND o.status='completed' AND o.completed_at>=@from AND o.completed_at<@to) AS revenue,(SELECT COALESCE(sum(amount),0) FROM commissions cm WHERE cm.user_id=u.id AND cm.status IN ('pending','approved')) AS outstanding FROM users u WHERE u.role='ctv' AND (@owner IS NULL OR u.id=@owner) ORDER BY revenue DESC,u.name,u.id LIMIT 10",args,tx):Array.Empty<object>();
        var missing=ctx.User().Manager?await c.ExecuteScalarAsync<int>("SELECT count(*) FROM products p JOIN product_models m ON m.id=p.model_id JOIN product_categories cat ON cat.id=m.category_id WHERE p.active AND m.active AND cat.active AND NOT EXISTS(SELECT 1 FROM prices pr WHERE pr.product_id=p.id AND pr.channel='retail')",transaction:tx):0;
        var accountCount=ctx.User().Manager?await c.ExecuteScalarAsync<int>("SELECT count(*) FROM users WHERE role='ctv' AND active",transaction:tx):0;
        await tx.CommitAsync();return Results.Ok(new{quotes,live,orders,commissions,recent,team,missingPrices=missing,activeCtvs=accountCount});
    });}
}
